//
// The week builder, checked against the web engine that wrote the weeks Lucy
// has been training on.
//
// Fixtures/planner.json was generated by running lib/generateRoutine over
// 1,890 combinations of level, equipment, training days, day types and
// favourites, and keeping every week it produced. A single lift in a single
// slot in a different order fails this, which is the point: the order is what
// makes a week reproducible, and a sort that is stable in one language and
// not in the other would silently change somebody's Monday.

import XCTest
@testable import HabitaBullKit

private struct Fixture: Decodable {
    // compact arrays rather than objects: this file is 1,890 weeks long
    let catalogue: [[JSON]]
    let types: [[JSON]]
    let coverage: [[JSON]]
    let cases: [[JSON]]
}

/// Just enough of a JSON value to read a fixture written as mixed arrays.
private enum JSON: Decodable {
    case string(String), number(Double), bool(Bool), list([JSON]), null

    init(from decoder: Decoder) throws {
        let c = try decoder.singleValueContainer()
        if c.decodeNil() { self = .null }
        else if let s = try? c.decode(String.self) { self = .string(s) }
        else if let b = try? c.decode(Bool.self) { self = .bool(b) }
        else if let d = try? c.decode(Double.self) { self = .number(d) }
        else { self = .list(try c.decode([JSON].self)) }
    }

    var text: String { if case .string(let s) = self { return s }; return "" }
    var num: Double { if case .number(let d) = self { return d }; return 0 }
    var int: Int { Int(num) }
    /// Written either as a real boolean or as 1/0, depending on the field.
    var flag: Bool {
        if case .bool(let b) = self { return b }
        return num == 1
    }
    var items: [JSON] { if case .list(let a) = self { return a }; return [] }
    var isNull: Bool { if case .null = self { return true }; return false }
}

final class PlannerParityTests: XCTestCase {
    private func load() throws -> Fixture {
        let url = try XCTUnwrap(Bundle.module.url(forResource: "planner", withExtension: "json"))
        return try JSONDecoder().decode(Fixture.self, from: Data(contentsOf: url))
    }

    func testTheDayTypesAreTheSameSevenInTheSameOrder() throws {
        let f = try load()
        XCTAssertEqual(f.types.count, DayTypes.all.count)
        for (row, mine) in zip(f.types, DayTypes.all) {
            XCTAssertEqual(row[0].text, mine.id)
            XCTAssertEqual(row[1].text, mine.label, "label of \(mine.id)")
            XCTAssertEqual(row[2].text, mine.hint, "hint of \(mine.id)")
            XCTAssertEqual(row[3].items.map(\.text), mine.muscles, "muscles of \(mine.id)")
            XCTAssertEqual(row[4].flag, mine.circuit, "style of \(mine.id)")
            XCTAssertEqual(row[5].isNull ? nil : row[5].items.map(\.text), mine.lifts, "named lifts of \(mine.id)")
            XCTAssertEqual(row[6].flag, mine.recommended, "recommended flag of \(mine.id)")
        }
    }

    func testTwiceAWeekCoverageAgrees() throws {
        for row in try load().coverage {
            let ids = row[0].items.map(\.text)
            XCTAssertEqual(DayTypes.coversTwiceWeekly(ids), row[1].flag, "\(ids)")
        }
    }

    func testEveryWeekMatchesTheWebEngine() throws {
        let f = try load()
        let catalogue = f.catalogue.map {
            Lift(id: $0[0].text, name: $0[1].text, equipment: $0[2].text, primary: $0[3].text,
                 increment: $0[4].num, compound: $0[5].flag, heavy: $0[6].flag,
                 hold: $0[7].flag, cardio: $0[8].flag)
        }
        XCTAssertGreaterThan(catalogue.count, 50, "the catalogue looks truncated")
        XCTAssertGreaterThan(f.cases.count, 1000, "the fixture looks truncated")

        var drifted: [String] = []
        for c in f.cases {
            let level = Level(rawValue: c[0].text)!
            let equipment = c[1].items.map(\.text)
            let days = c[2].items.map(\.int)
            let types = c[3].isNull ? nil : c[3].items.map(\.text)
            let favourites = c[4].items.map(\.text)
            let want = c[5].items
            let got = Planner.generate(level: level, days: days, equipment: equipment,
                                       favourites: favourites, dayTypes: types, catalogue: catalogue)
            let what = "\(level.rawValue) · \(equipment) · days \(days) · \(types.map { "\($0)" } ?? "default") · fav \(favourites)"

            guard got.count == want.count else {
                drifted.append("\(what): \(got.count) days vs \(want.count)")
                continue
            }
            for (mine, theirs) in zip(got, want) {
                let row = theirs.items
                if mine.day != row[0].int { drifted.append("\(what): day \(mine.day) vs \(row[0].int)") }
                if mine.label != row[1].text { drifted.append("\(what): label \(mine.label) vs \(row[1].text)") }
                if mine.dayType != row[2].text { drifted.append("\(what): type \(mine.dayType) vs \(row[2].text)") }
                let lifts = row[3].items
                if mine.exercises.count != lifts.count {
                    drifted.append("\(what) \(mine.label): \(mine.exercises.count) lifts vs \(lifts.count)")
                    continue
                }
                for (e, l) in zip(mine.exercises, lifts) {
                    let f = l.items
                    if e.exerciseId != f[0].text { drifted.append("\(what) \(mine.label): \(e.exerciseId) vs \(f[0].text)") }
                    if e.sets != f[1].int { drifted.append("\(what) \(e.exerciseId): sets \(e.sets) vs \(f[1].int)") }
                    if e.reps != f[2].int { drifted.append("\(what) \(e.exerciseId): reps \(e.reps) vs \(f[2].int)") }
                    if abs(e.weight - f[3].num) > 0.0001 { drifted.append("\(what) \(e.exerciseId): weight \(e.weight) vs \(f[3].num)") }
                }
            }
        }
        XCTAssertEqual(Array(drifted.prefix(10)), [], "\(drifted.count) differences from the web engine")
    }
}
